package edu.hfut.access.service.impl;
import java.util.*;import java.util.concurrent.*;import java.security.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.time.format.*;import java.net.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.beans.factory.annotation.Value;import com.fasterxml.jackson.databind.ObjectMapper;import edu.hfut.access.dao.*;import edu.hfut.access.client.*;import edu.hfut.access.dto.*;import edu.hfut.access.exception.ApiException;import edu.hfut.access.service.*;import static edu.hfut.access.security.Identity.*;
@Service public class AccessOperationsImpl implements AccessOperations{
 private final AccessMapper dao;private final DirectoryClient users;private final AppointmentClient appointments;private final SafetyClient safety;private final ObjectMapper json;private final AccessPolicy policy;private final SecureRandom random=new SecureRandom();private final ConcurrentMap<Integer,Integer> counts=new ConcurrentHashMap<>();
 @Value("${P4_INTERNAL_KEY}")String key;
 public AccessOperationsImpl(AccessMapper d,DirectoryClient u,AppointmentClient a,SafetyClient s,ObjectMapper j,AccessPolicy p){dao=d;users=u;appointments=a;safety=s;json=j;policy=p;}
 private Map<String,Object> map(Object...pairs){Map<String,Object>r=new LinkedHashMap<>();for(int i=0;i<pairs.length;i+=2)r.put(String.valueOf(pairs[i]),pairs[i+1]);return r;}
 private Context context(String token,Map<String,Object>b,String action){Map<String,Object>request=new HashMap<>(b);request.put("action",action);Context c=users.resolve(key,"Bearer "+(token==null?"":token),request);if(c==null||c.unavailable||c.actor==null)throw new ApiException(503,"身份验证服务不可用");counts.merge(c.servedBy,1,Integer::sum);return c;}
 public Object instanceCounts(){return counts;}
 private void permission(Context c,String table,boolean write){if(Arrays.asList("gates","settings","access_rules").contains(table))require(c,"admin");else if(table.equals("qr_codes"))require(c,"visitor","alumni","guard","admin");else{require(c,"guard","admin");if(write&&table.equals("devices")&&!text(c.actor,"role").equals("admin"))throw new ApiException(403,"只有管理员可以维护设备");}}
 private boolean owns(Context c,Map<String,Object>q){String role=text(c.actor,"role");return role.equals("guard")||role.equals("admin")||Objects.equals(q.get("ownerId"),c.actor.get("personId"))||Objects.equals(q.get("visitorId"),c.actor.get("personId"))||c.person!=null&&Objects.equals(q.get("ownerName"),c.person.get("name"));}
 private String now(){return LocalDateTime.now(ZoneId.of("Asia/Shanghai")).format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));}
 private String id(String prefix){return prefix+LocalDate.now(ZoneId.of("Asia/Shanghai")).format(DateTimeFormatter.BASIC_ISO_DATE)+UUID.randomUUID().toString().replace("-","").toUpperCase(Locale.ROOT);}
 private Map<String,Object> one(String table,String id){for(Map<String,Object>r:rows(table))if(Objects.equals(r.get("id"),id))return r;return null;}
 private List<Map<String,Object>> rows(String table){List<Map<String,Object>>r=dao.list(table);if(table.equals("access_rules"))for(Map<String,Object>x:r)for(String f:Arrays.asList("methods","gates")){Object v=x.get(f);if(v instanceof String&&((String)v).startsWith("["))try{x.put(f,json.readValue((String)v,List.class));}catch(Exception e){throw new ApiException(500,"通行规则存储格式不正确");}}return r;}
 private void save(String op,String table,Map<String,Object>row){Map<String,Object>db=new HashMap<>(row);if(table.equals("access_rules"))for(String f:Arrays.asList("methods","gates"))if(db.get(f)instanceof List)db.put(f,encode(db.get(f)));if(op.equals("insert"))dao.insert(table,db);else dao.update(table,db);}
 private String encode(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException("Serialization failed");}}
 private void required(Map<String,Object>b,String message,String...fields){List<String>missing=new ArrayList<>();for(String f:fields)if(text(b,f).trim().isEmpty())missing.add(f);if(!missing.isEmpty())throw new ApiException(400,message,Collections.singletonMap("missing",missing));}
 private Map<String,Object> enrich(Map<String,Object>r,List<Map<String,Object>>people){Map<String,Object>x=new LinkedHashMap<>(r);x.put("personCode","");for(Map<String,Object>p:people)if(Objects.equals(p.get("id"),r.get("personId"))){x.put("personCode",p.get("code"));break;}return x;}
 public Object list(String token,String table,Map<String,String>query){Context c=context(token,Collections.emptyMap(),"identity");permission(c,table,false);List<Map<String,Object>>out=new ArrayList<>(),people=table.equals("access_records")?users.people(key):Collections.emptyList();if(people==null)throw new ApiException(503,"人员服务不可用");for(Map<String,Object>r:rows(table)){
  if(table.equals("qr_codes")&&(!owns(c,r)||"预备".equals(r.get("status"))))continue;Map<String,Object>x=table.equals("access_records")?enrich(r,people):new LinkedHashMap<>(r);boolean accept=true;
  for(String f:table.equals("access_records")?Arrays.asList("status","type","gate","method"):table.equals("qr_codes")?Arrays.asList("status","type"):table.equals("devices")?Arrays.asList("status","gate"):Collections.<String>emptyList())if(query.containsKey(f)&&!query.get(f).isEmpty()&&!Objects.equals(x.get(f),query.get(f)))accept=false;
  for(String f:table.equals("access_records")?Arrays.asList("name"):table.equals("qr_codes")?Arrays.asList("ownerName"):Collections.<String>emptyList())if(query.containsKey(f)&&!text(x,f).contains(query.get(f)))accept=false;
  if(table.equals("access_records")&&query.containsKey("keyword")){String v=query.get("keyword").trim();boolean match=false;for(String f:Arrays.asList("id","time","name","personCode","type","method","gate","status"))if(text(x,f).contains(v))match=true;if(!match)accept=false;}
  if(table.equals("access_records")&&query.containsKey("timeFrom")&&!query.get("timeFrom").isEmpty()&&text(x,"time").compareTo(query.get("timeFrom"))<0)accept=false;if(table.equals("access_records")&&query.containsKey("timeTo")&&!query.get("timeTo").isEmpty()&&text(x,"time").compareTo(query.get("timeTo"))>0)accept=false;
  if(table.equals("gates")&&!AccessPolicy.GATES.contains(x.get("name")))accept=false;
  if(table.equals("access_rules")){if("管理员".equals(x.get("role")))x.put("role","保卫处管理员");if(!AccessPolicy.LABELS.containsValue(x.get("role")))accept=false;List<String>gs=AccessPolicy.list(x.get("gates"));if(gs.contains("全部校门")||gs.contains("值守校门"))gs=AccessPolicy.GATES;List<String>sorted=new ArrayList<>();for(String g:AccessPolicy.GATES)if(gs.contains(g))sorted.add(g);x.put("gates",String.join("、",sorted));}
  if(accept)out.add(x);
 }if(table.equals("gates")){List<Map<String,Object>>ordered=new ArrayList<>();for(String name:AccessPolicy.GATES)for(Map<String,Object>x:out)if(name.equals(x.get("name"))){ordered.add(x);break;}out=ordered;}if(table.equals("access_records"))try{double n=Double.parseDouble(query.getOrDefault("limit","0"));if(n>0&&n<out.size())out=new ArrayList<>(out.subList(0,(int)n));}catch(Exception e){}return Envelope.list(out);}
 private Map<String,Object> appointment(String id){Map<String,Object>r=appointments.one(key,id);if(r==null||Boolean.TRUE.equals(r.get("unavailable")))throw new ApiException(503,"预约验证服务不可用");return Boolean.TRUE.equals(r.get("accessAllowed"))?(Map<String,Object>)r.get("appointment"):null;}
 private void bind(Context c,Map<String,Object>owner,Map<String,Object>a){if(a==null||!"已通过".equals(a.get("status"))||!(Objects.equals(a.get("visitorId"),owner.get("id"))||Objects.equals(a.get("visitorPhone"),owner.get("phone"))||Objects.equals(a.get("visitor"),owner.get("name"))))throw new ApiException(400,"访客二维码必须绑定本人已通过的预约");}
 @Transactional(isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED) public Object create(String token,String table,Map<String,Object>b){Context c=context(token,Collections.emptyMap(),"identity");permission(c,table,true);
  if(table.equals("qr_codes")){
   String role=text(c.actor,"role"),type=role.equals("visitor")?"visitor":role.equals("alumni")?"alumni":text(b,"type");if(type.isEmpty())throw new ApiException(400,"二维码类型不能为空");if(role.equals("admin"))c=context(token,b,"select");Map<String,Object>owner=c.person;if(owner==null)throw new ApiException(404,"二维码所属人员不存在");if("visitor".equals(owner.get("role"))&&!type.equals("visitor"))throw new ApiException(403,"访客不能使用其他类型二维码");Map<String,Object>a=type.equals("visitor")?appointment(text(b,"appointmentId")):null;if(type.equals("visitor"))bind(c,owner,a);if(!role.equals("admin")&&!role.equals(type))throw new ApiException(403,"无权生成该类型二维码");
   if(a!=null){for(Map<String,Object>q:dao.list("qr_codes"))if(Objects.equals(q.get("appointmentId"),a.get("id"))){if(!"有效".equals(q.get("status")))throw new ApiException(409,"预约凭证已撤销，不能重复签发");return q;}}
   String date=LocalDate.now(ZoneId.of("Asia/Shanghai")).toString(),start=a!=null?text(a,"visitStart"):text(b,"validFrom"),end=a!=null?text(a,"visitEnd"):text(b,"validTo");if(start.isEmpty())start=date+" 08:00:00";if(end.isEmpty())end=date+" 18:00:00";
   byte[]bytes=new byte[32];random.nextBytes(bytes);Map<String,Object>q=map("id",id("Q"),"token",Base64.getUrlEncoder().withoutPadding().encodeToString(bytes),"type",type,"ownerName",owner.get("name"),"ownerId",owner.get("id"),"visitorId",type.equals("visitor")?owner.get("id"):null,"appointmentId",a!=null?a.get("id"):b.get("appointmentId"),"validFrom",start,"validTo",end,"status","有效");save("insert",table,q);return q;
  }if(table.equals("devices")){if(text(b,"name").trim().isEmpty()||text(b,"type").trim().isEmpty()||text(b,"gate").trim().isEmpty())throw new ApiException(400,"请填写设备名称、设备类型和所属校门");Map<String,Object>d=map("id",text(b,"id").isEmpty()?id("D"):b.get("id"),"name",b.get("name"),"type",b.get("type"),"gate",b.get("gate"),"status",text(b,"status").isEmpty()?"在线":b.get("status"));deviceGate(d);save("insert",table,d);return d;}
  required(b,"通行记录信息不完整","name","type","method","gate","status");c=context(token,b,"record");if(c.person==null&&!Arrays.asList("人工核验后放行","现场放行").contains(b.get("method")))throw new ApiException(404,"未找到人员，只有人工核验后放行或现场放行可手工登记陌生人员");Map<String,Object>r=map("id",id("R"),"time",text(b,"time").isEmpty()?now():b.get("time"),"name",c.person==null?b.get("name"):c.person.get("name"),"personId",c.person==null?null:c.person.get("id"),"type",c.person==null?b.get("type"):c.person.get("type"),"method",b.get("method"),"gate",b.get("gate"),"status",b.get("status"));save("insert",table,r);r.put("personCode",c.person==null?"":c.person.get("code"));return r;
 }
 private void deviceGate(Map<String,Object>d){for(Map<String,Object>g:dao.list("gates"))if(Objects.equals(g.get("name"),d.get("gate"))&&"维护中".equals(g.get("status")))d.put("status","维护中");}
 @Transactional(isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED) public Object update(String token,String table,String id,Map<String,Object>b,boolean delete){Context c=context(token,Collections.emptyMap(),"identity");permission(c,table,true);Map<String,Object>r=one(table,id);String noun=table.equals("devices")?"设备":table.equals("gates")?"校门":table.equals("qr_codes")?"二维码":"通行规则";if(r==null)throw new ApiException(404,noun+"不存在");if(table.equals("qr_codes")){if(!owns(c,r)||text(c.actor,"role").equals("guard"))throw new ApiException(403,"无权撤销该二维码");dao.lock(id);r.put("status","已撤销");save("update",table,r);return r;}if(delete){dao.delete(table,r);return r;}
  if(table.equals("gates")){if(b.containsKey("status")&&!Arrays.asList("开放","维护中","关闭").contains(b.get("status")))throw new ApiException(400,"校门状态不正确");if(b.containsKey("name")&&!AccessPolicy.GATES.contains(b.get("name")))throw new ApiException(400,"校门名称不正确");if(!AccessPolicy.GATES.contains(r.get("name")))throw new ApiException(404,"校门不存在");}
  if(table.equals("access_rules")){if(b.containsKey("methods")&&(AccessPolicy.list(b.get("methods")).isEmpty()||!AccessPolicy.METHODS.containsAll(AccessPolicy.list(b.get("methods")))))throw new ApiException(400,"认证方式不正确");if(b.containsKey("gates")&&(AccessPolicy.list(b.get("gates")).isEmpty()||!AccessPolicy.GATES.containsAll(AccessPolicy.list(b.get("gates")))))throw new ApiException(400,"允许校门不正确");if(b.containsKey("status")&&!Arrays.asList("启用","停用").contains(b.get("status")))throw new ApiException(400,"通行规则状态不正确");if(b.containsKey("allowedTime")&&!Arrays.asList("全天时间","全天","预约时段","预约时段内").contains(b.get("allowedTime"))&&!text(b,"allowedTime").matches("([01]\\d|2[0-3]):[0-5]\\d-([01]\\d|2[0-3]):[0-5]\\d"))throw new ApiException(400,"允许时间不正确");}
  String oldName=text(r,"name");List<String>fields=table.equals("devices")?Arrays.asList("name","type","gate","status"):table.equals("gates")?Arrays.asList("name","campus","location","openTime","status"):Arrays.asList("methods","allowedTime","gates","status");for(String f:fields)if(b.containsKey(f))r.put(f,b.get(f));if(table.equals("devices"))deviceGate(r);if(table.equals("gates"))for(Map<String,Object>d:dao.list("devices"))if(oldName.equals(d.get("gate"))||!oldName.equals(text(r,"name"))&&Objects.equals(d.get("gate"),r.get("name"))){d.put("gate",r.get("name"));if("维护中".equals(r.get("status")))d.put("status","维护中");else if("开放".equals(r.get("status"))&&"维护中".equals(d.get("status")))d.put("status","在线");save("update","devices",d);}save("update",table,r);return r;
 }
 private String extract(String s){String raw=s.trim();try{Map<String,Object>m=json.readValue(raw,Map.class);if(m.get("token")!=null)return text(m,"token");if(m.get("qrToken")!=null)return text(m,"qrToken");}catch(Exception e){}java.util.regex.Matcher m=java.util.regex.Pattern.compile("[?&]token=([^&\\s]+)").matcher(raw);if(m.find())try{return URLDecoder.decode(m.group(1),"UTF-8");}catch(Exception e){}return raw;}
 private Map<String,Object>qr(String value){for(Map<String,Object>q:dao.list("qr_codes"))if(value.equals(q.get("id"))||value.equals(q.get("token")))return q;return null;}
 private AccessPolicy.Decision decision(String token,Map<String,Object>b,Map<String,Object>q,boolean isQr){String kind=text(b,"credentialType"),value=extract(text(b,"credentialValue"));Map<String,Object>request=new HashMap<>(b);if(isQr&&q!=null)request.put("personId",q.get("ownerId")!=null?q.get("ownerId"):q.get("visitorId"));if(!isQr)request.remove("personId");Context c=context(token,request,isQr?"qr-person":"scan");String reason="";
  if(isQr&&q!=null&&("visitor".equals(q.get("type"))||c.person!=null&&"visitor".equals(c.person.get("role")))){Map<String,Object>a=appointment(text(q,"appointmentId"));if(a==null||!"已通过".equals(a.get("status"))||c.person==null||!(Objects.equals(a.get("visitorId"),c.person.get("id"))||Objects.equals(a.get("visitorPhone"),c.person.get("phone"))||Objects.equals(a.get("visitor"),c.person.get("name"))))reason="预约未完成审批或绑定身份不匹配";}
  Map<String,Object>check=safety.check(key,map("person",c.person,"qrCode",q,"credential",value));if(check==null||!Boolean.TRUE.equals(check.get("available")))throw new ApiException(503,"黑名单服务不可用");if(Boolean.TRUE.equals(check.get("blocked")))reason="命中黑名单："+text(check,"reason");
  List<Map<String,Object>>settings=dao.list("settings");AccessPolicy.Decision d=policy.decide(c,q,kind,text(b,"gate"),text(b,"method"),dao.list("gates"),rows("access_rules"),settings.isEmpty()?Collections.emptyMap():settings.get(0),reason);
  if(b.containsKey("deviceId")){Map<String,Object>device=one("devices",text(b,"deviceId"));if(device==null||!"在线".equals(device.get("status"))||d.gate!=null&&!Objects.equals(device.get("gate"),d.gate.get("name")))d.deny("设备状态不可用或校门不匹配");}return d;
 }
 @Transactional(isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED) public Object evaluate(String token,Map<String,Object>input,boolean record,String requestId){Context actor=context(token,Collections.emptyMap(),"identity");require(actor,record?new String[]{"guard","admin"}:new String[]{"admin"});Map<String,Object>b=new HashMap<>(input);String kind=text(b,"credentialType");if(kind.isEmpty())kind=record?"qr":"campusCard";b.put("credentialType",kind);String value=extract(text(b,"credentialValue").isEmpty()?text(b,"token"):text(b,"credentialValue"));if(value.isEmpty())throw new ApiException(400,record?"缺少识别凭证":"请填写需要验证的通行凭证");b.put("credentialValue",value);if(text(b,"gate").isEmpty())b.put("gate","东门");
  Map<String,Object> replay=null;String digest=null;if(record&&requestId!=null&&!requestId.isEmpty()){if(!requestId.matches("[A-Za-z0-9_-]{8,128}"))throw new ApiException(400,"核验请求标识不正确");try{digest=Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-256").digest((text(actor.actor,"id")+encode(new TreeMap<>(b))).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException();}dao.reserveRequest(requestId,digest);Map<String,Object>r=dao.request(requestId);if(!digest.equals(r.get("request_digest")))throw new ApiException(409,"核验请求标识已用于其他请求");if(r.get("response_json")!=null)try{replay=json.readValue(String.valueOf(r.get("response_json")),Map.class);}catch(Exception e){throw new ApiException(500,"核验记录读取失败");}}
  boolean isQr=Arrays.asList("qr","visitorQr","alumniQr").contains(kind);Map<String,Object>q=isQr?qr(value):null;if(q!=null){dao.lock(text(q,"id"));q=qr(value);}AccessPolicy.Decision d=decision(token,b,q,isQr);if(replay!=null){if(!d.allowed&&Boolean.TRUE.equals(replay.get("allowed")))throw new ApiException(409,"核验状态已变化");return replay;}Object result;
  if(!record){result=map("allowed",d.allowed,"reason",d.reason,"credentialType",kind,"method",isQr?text(b,"method"):d.method,"person",d.person==null?null:map("id",d.person.get("id"),"name",d.person.get("name"),"type",d.person.get("type"),"role",d.person.get("role"),"code",d.person.get("code")),"gate",d.gate==null?null:map("id",d.gate.get("id"),"name",d.gate.get("name"),"status",d.gate.get("status"),"openTime",d.gate.get("openTime")),"rule",d.rule);}
  else{Map<String,Object>r=map("id",id("R"),"time",now(),"name",d.person!=null?d.person.get("name"):q!=null?q.get("ownerName"):"未知人员","personId",d.person==null?null:d.person.get("id"),"type",q!=null&&"alumni".equals(q.get("type"))?"校友":q!=null&&"visitor".equals(q.get("type"))?"访客":d.person==null?"未知":d.person.get("type"),"method",d.method,"gate",d.gate==null?b.get("gate"):d.gate.get("name"),"status",d.allowed?"正常":"异常");save("insert","access_records",r);Map<String,Object>event=map("record",r,"reason",d.reason,"allowed",d.allowed,"actor",actor.actor,"vehicle",d.allowed?d.vehicle:null);dao.event("ACCESS-"+r.get("id"),"ACCESS_RESULT",encode(event));r.put("personCode",d.person==null?"":d.person.get("code"));result=map("record",r,"qrCode",q,"allowed",d.allowed,"reason",d.reason,"rule",d.rule);}
  if(record&&digest!=null)dao.completeRequest(requestId,encode(result));return result;
 }
 public Object verify(String token,String id,Map<String,Object>b){Context actor=context(token,Collections.emptyMap(),"identity");permission(actor,"qr_codes",false);Map<String,Object>q=qr(extract(id));if(q==null)throw new ApiException(404,"二维码不存在");if(!owns(actor,q))throw new ApiException(403,"无权核验该二维码");
  // User-authorized verification uses their current own identity; scanner identities use guarded scan context.
  Map<String,Object>request=new HashMap<>(b);request.put("credentialType","qr");request.put("credentialValue",text(q,"token"));if(text(request,"gate").isEmpty())request.put("gate","东门");AccessPolicy.Decision d=decision(token,request,q,true);return map("qrCode",q,"allowed",d.allowed,"gate",d.gate==null?request.get("gate"):d.gate.get("name"),"reason",d.reason);
 }
}
